css:
* {
  font-size:12px;
}

.print-format{ 
    font-family: Inter, "Helvetica Neue", Helvetica, Arial, "Open Sans", sans-serif !important;
}

.circle-index {
    display: inline-block;
    width: 15px;
    height: 15px;
    line-height: 15px;
    border-radius: 50%;
    border: 1px solid #cccccc;
    background-color: #e2e2e2;
    color: black;
    text-align: center;
    font-size: 12px;
    font-weight: bold;
    margin-right: 1px;
}


.sku-box {
    display: inline-block;
    background-color: #eaeaea;
    color: #393d47;
    padding: 0px 4px;
    border: 1px solid #cccccc;
    border-radius: 4px;
    font-size: 12px;
    font-weight: bold;
    line-height: 1.4;
    margin-left: 1px;
}



table.div-striped > thead > tr {
    background-color: transparent;
    border-bottom: 5px solid transparent;
}

table.div-striped > thead > tr > th {
    background-color: #0a1f41;
}

table.div-striped > thead > tr > th:first-child() {
    border-radius: 20px 0 20px 0;
}

table.div-striped > thead > tr > th:last-child() {
    border-radius: 0 20px 0 20px;
}


table.div-striped > thead > tr > th > span {
    font-weight: bold;
    color: #fcfcfc;
}

table.div-striped > tbody > tr.row-odd {
    background-color: #f5f5f5;
}

table.div-striped > tbody > tr.row-even {
    background-color: #fff;
}

table.div-striped > tbody > tr > td {
    background-color: transparent;
}

.heading {
    background-color: color(srgb 0.1562 0.1663 0.3571) !important/* Color para el encabezado de la tabla */
}

.div-striped td {
    padding: 8px;
}


.print-format th{
    padding: 2px !important;
}
.print-format td {
    padding: 1px !important;
}

table {
    border: none;
}

table tr td,
table tr th {
    border: 0px solid #ebebeb !important;
}

.total-row {
    border: none !important;
}
.total-row th {
    text-align: right !important;
    border: none !important;
}

.total-row td {
    font-weight: bold;
}

/*---------------footer----------------*/

.yes_letterhead{
    /*height: 696px;*/
    border: 1px solid #FFF;
    overflow:hidden;
}

.print-format {
}

body {
    min-height: 9.818898in;
}





/* Ajuste fino de celdas */
table td {
    padding: 4px !important;
    margin: 0;
    vertical-align: top;
    border: 0px solid #ebebeb !important;
}

/* Control de los divs internos de cada celda */
td .value {
    margin: 0 !important;
    padding: 0 !important;
    line-height: 1.3;
    display: block;
    text-align: justify;
}

/* Estilo estándar para tabla con filas alternas */
table.div-striped > tbody > tr.row-odd {
    background-color: #f5f5f5;
}
table.div-striped > tbody > tr.row-even {
    background-color: #fff;
}
